uint16_t dsky_monitor_checkpoint(uint16_t n,apollo_overlay_state *s,apollo_overlay_state *before){dsky_charin_io io,old;enum dsky_nv_mission mission;enum dsky_monitor_stage stage;enum dsky_monitor_route route=(enum dsky_monitor_route)99;uint16_t f,p,end,failures=0;if(n>=DSKY_MONITOR_FROZEN_COUNT)return 1;dsky_monitor_input(s,&io,dsky_monitor_numbers[n],&mission,&stage);*before=*s;old=io;if(dsky_monitor(s,&io,mission,stage,&route)!=P66_BIAS_OK)++failures;p=dsky_monitor_offsets[n];end=dsky_monitor_offsets[n+1u];for(f=0;f<2053u;++f){uint16_t expected=f<2048u?before->words[f]:f==2048u?old.control.superbank:f==2049u?old.control.interrupt_enabled:f==2050u?old.channel11:f==2051u?old.wrote_channel11:99;uint16_t actual=f<2048u?s->words[f]:f==2048u?io.control.superbank:f==2049u?io.control.interrupt_enabled:f==2050u?io.channel11:f==2051u?io.wrote_channel11:(uint16_t)route;if(p<end&&dsky_monitor_patch[p][0]==f)expected=dsky_monitor_patch[p++][1];if(actual!=expected)++failures;}if(p!=end)++failures;return failures;}
